const $ = (selector) => document.querySelector(selector);
const $$ = (selector) => [...document.querySelectorAll(selector)];

const manualCandidateSelectionKey = "dino-atlas-manual-candidate-selections-v1";
const candidateReviewDecisionKey = "dino-atlas-candidate-review-decisions-v1";

function loadManualCandidateSelections() {
  try {
    return JSON.parse(localStorage.getItem(manualCandidateSelectionKey) || "{}") || {};
  } catch {
    return {};
  }
}

let manualCandidateSelections = loadManualCandidateSelections();

function saveManualCandidateSelections() {
  try {
    localStorage.setItem(manualCandidateSelectionKey, JSON.stringify(manualCandidateSelections));
  } catch {
    // The app still works without persistence when storage is unavailable.
  }
}

function loadCandidateReviewDecisions() {
  try {
    return JSON.parse(localStorage.getItem(candidateReviewDecisionKey) || "{}") || {};
  } catch {
    return {};
  }
}

let candidateReviewDecisions = loadCandidateReviewDecisions();

function saveCandidateReviewDecisions() {
  try {
    localStorage.setItem(candidateReviewDecisionKey, JSON.stringify(candidateReviewDecisions));
  } catch {
    // Review labels are helpful, but the page remains usable without storage.
  }
}

