function isStructurallyRejectedCandidate(item) {
  const source = item?.source || item?.src || "";
  return structurallyRejectedCandidateKinds.has(item?.kind) || verifiedRejectedCandidateSources.has(source);
}

const gallerySlotRoleLabels = {
  representative: "대표 전신",
  "color-pattern": "색상·무늬 변형",
  "habitat-ecology": "서식지·일상 생태",
  "identity-anatomy": "종 고유 구조",
  interaction: "생태 상호작용",
  "social-growth-defense": "사회·성장·방어",
  "alternate-habitat-behavior": "대체 서식지·행동",
};

const gallerySlotAssignmentProblems = [];

function applyGallerySlotAssignments() {
  const assignments = globalThis.gallerySlotAssignments || {};
  Object.values(generatedImageSamples).flat().forEach((candidate) => {
    if (!candidate || typeof candidate !== "object") return;
    delete candidate.gallerySlot;
    delete candidate.galleryRole;
    delete candidate.phenotype;
    delete candidate.habitatKey;
    delete candidate.expectedKind;
  });
  Object.entries(assignments).forEach(([taxonId, taxonAssignments]) => {
    const candidates = generatedImageSamples[taxonId] || [];
    taxonAssignments.forEach((assignment) => {
      const item = candidates.find(
        (candidate) =>
          candidate &&
          typeof candidate === "object" &&
          (candidate.src === assignment.source || candidate.source === assignment.source),
      );
      if (!item) {
        gallerySlotAssignmentProblems.push(`${taxonId}:${assignment.gallerySlot}:${assignment.source}`);
        return;
      }
      Object.assign(item, assignment);
    });
  });
}

applyGallerySlotAssignments();

const anatomyCandidateRank = {
  "primary generated": 0,
  "primary structure reference": 0,
  "count-level pass": 0,
  "anatomy review": 1,
  "structure reference": 2,
  "diagnostic only": 3,
};

const userGalleryHiddenKinds = new Set(["diagnostic only"]);

function getKnowledgeLevel(level) {
  return knowledgeLevels[level] || knowledgeLevels[4];
}

function getEraLabel(eraId) {
  return eras.find((era) => era.id === eraId)?.label || "";
}

function getPrimaryFeatureText(dino, limit = 3) {
  return Object.entries(dino.features)
    .slice(0, limit)
    .map(([key, value]) => `${key}: ${value}`)
    .join(" · ");
}

function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function getCandidateKey(item) {
  return item?.source || item?.src || item?.title || "";
}

function getCandidateGeneratedTimestamp(item) {
  const value = item?.generatedAt || item?.createdAt || item?.updatedAt || "";
  const timestamp = Date.parse(value);
  return Number.isFinite(timestamp) ? timestamp : 0;
}

function compareReviewCandidatesByLatest(a, b) {
  const timestampDelta = getCandidateGeneratedTimestamp(b) - getCandidateGeneratedTimestamp(a);
  if (timestampDelta) return timestampDelta;
  const kindDelta = (anatomyCandidateRank[a.kind] ?? 4) - (anatomyCandidateRank[b.kind] ?? 4);
  if (kindDelta) return kindDelta;
  return getCandidateKey(a).localeCompare(getCandidateKey(b), "ko");
}

function getAllCandidates(dino) {
  return [...(generatedImageSamples[dino.id] || [])]
    .filter((item) => !isStructurallyRejectedCandidate(item))
    .sort(
    (a, b) => (anatomyCandidateRank[a.kind] ?? 4) - (anatomyCandidateRank[b.kind] ?? 4),
  );
}

function getManualCandidateSource(dino) {
  const selectedSource = manualCandidateSelections[dino.id];
  if (!selectedSource) return "";
  return getAllCandidates(dino).some(
    (item) => getCandidateKey(item) === selectedSource && !isUserHiddenCandidate(item),
  )
    ? selectedSource
    : "";
}

function isUserHiddenCandidate(item) {
  return userGalleryHiddenKinds.has(item?.kind) || isInternalReviewCandidate(item);
}

function isCandidateHiddenFromUserGallery(item, dino) {
  return isUserHiddenCandidate(item);
}

function getGeneratedImages(dino, options = {}) {
  const includeDiagnostics = Boolean(options.includeDiagnostics);
  const selectedSource = getManualCandidateSource(dino);
  return getAllCandidates(dino)
    .filter((item) => includeDiagnostics || !isCandidateHiddenFromUserGallery(item, dino))
    .sort((a, b) => {
      const aSelected = getCandidateKey(a) === selectedSource;
      const bSelected = getCandidateKey(b) === selectedSource;
      if (aSelected !== bSelected) return aSelected ? -1 : 1;
      return (anatomyCandidateRank[a.kind] ?? 4) - (anatomyCandidateRank[b.kind] ?? 4);
    });
}

function getPrimaryImage(dino) {
  return getSlottedGalleryImages(dino).find((item) => item.gallerySlot === 1) || getGeneratedImages(dino)[0] || null;
}

function getSlottedGalleryImages(dino) {
  const bySlot = new Map();
  getGeneratedImages(dino).forEach((item) => {
    const slot = Number(item.gallerySlot);
    if (!Number.isInteger(slot) || slot < 1 || slot > dino.imageSlots || bySlot.has(slot)) return;
    bySlot.set(slot, item);
  });
  return [...bySlot.values()].sort((left, right) => left.gallerySlot - right.gallerySlot);
}

function imageStyle(image) {
  return image?.src ? ` style="background-image: url('${image.src}')"` : "";
}

function getLightboxItem(item) {
  if (!item?.src) return null;
  return {
    src: item.src,
    kind: item.kind || "Image Review",
    title: item.title || item.variant || item.source || "후보 이미지",
    body: item.body || "",
    source: item.source || item.src,
  };
}

function getLightboxItems(items) {
  return items.map(getLightboxItem).filter(Boolean);
}

function renderLightbox() {
  const lightbox = $("#imageLightbox");
  if (!lightbox) return;
  const item = state.lightboxItems[state.lightboxIndex];
  const isOpen = Boolean(item);
  lightbox.hidden = !isOpen;
  lightbox.classList.toggle("active", isOpen);
  lightbox.setAttribute("aria-hidden", isOpen ? "false" : "true");
  document.body.classList.toggle("lightbox-open", isOpen);
  if (!isOpen) return;
  $("#lightboxImage").src = item.src;
  $("#lightboxImage").alt = item.title;
  $("#lightboxKind").textContent = item.kind;
  $("#lightboxTitle").textContent = item.title;
  $("#lightboxBody").textContent = item.body;
  $("#lightboxSource").textContent = item.source;
  $("#lightboxCount").textContent = `${state.lightboxIndex + 1} / ${state.lightboxItems.length}`;
}

function openLightbox(items, index = 0) {
  const lightboxItems = getLightboxItems(items);
  if (!lightboxItems.length) return;
  state.lightboxItems = lightboxItems;
  state.lightboxIndex = Math.max(0, Math.min(index, lightboxItems.length - 1));
  renderLightbox();
}

function openDinoGalleryLightbox(dino, selectedImage = getPrimaryImage(dino)) {
  const galleryItems = getGalleryItems(dino);
  const lightboxItems = getLightboxItems(galleryItems);
  const selectedIndex = lightboxItems.findIndex((item) => item.src === selectedImage?.src);
  if (selectedIndex >= 0) {
    openLightbox(galleryItems, selectedIndex);
    return;
  }
  if (selectedImage?.src) openLightbox([selectedImage], 0);
}

function closeLightbox() {
  state.lightboxItems = [];
  state.lightboxIndex = 0;
  renderLightbox();
}

function moveLightbox(delta) {
  const total = state.lightboxItems.length;
  if (!total) return;
  state.lightboxIndex = (state.lightboxIndex + delta + total) % total;
  renderLightbox();
}

function getGalleryItems(dino) {
  const bySlot = new Map(getSlottedGalleryImages(dino).map((item) => [item.gallerySlot, item]));
  return Array.from({ length: dino.imageSlots }, (_, index) => {
    const gallerySlot = index + 1;
    const assigned = bySlot.get(gallerySlot);
    if (assigned) return assigned;
    const role = Object.keys(gallerySlotRoleLabels)[index] || "alternate-habitat-behavior";
    const roleLabel = gallerySlotRoleLabels[role];
    return {
      gallerySlot,
      galleryRole: role,
      kind: "생성 예정",
      title: `${gallerySlot}번 슬롯 · ${roleLabel}`,
      body: `${dino.koreanName}의 ${roleLabel} 이미지가 아직 최종 배정되지 않았습니다. 종별 해부학과 팔레트를 유지한 후보만 이 슬롯에 들어갑니다.`,
      source: "Gallery slot generation plan",
      variant: "pending-slot",
    };
  });
}

function getFilteredDinosaurs() {
  const query = state.search.trim().toLowerCase();
  return dinosaurs.filter((dino) => {
    const dietMatches = state.diet === "all" || dino.diet.includes(state.diet);
    const levelMatches =
      state.knowledgeLevel === "all" || dino.knowledgeLevel === Number(state.knowledgeLevel);
    const text = [
      dino.name,
      dino.koreanName,
      dino.rootClade,
      dino.clade,
      dino.family,
      cladeMeta[dino.clade],
      ...(taxonomySearchAliases[dino.rootClade] || []),
      ...(taxonomySearchAliases[dino.clade] || []),
      dino.period,
      dino.region,
      getKnowledgeLevel(dino.knowledgeLevel).short,
      getKnowledgeLevel(dino.knowledgeLevel).label,
    ]
      .join(" ")
      .toLowerCase();
    return dietMatches && levelMatches && (!query || text.includes(query));
  });
}

function getDinoById(id) {
  return dinosaurs.find((dino) => dino.id === id);
}

function getFilteredIdSet() {
  return new Set(getFilteredDinosaurs().map((dino) => dino.id));
}

function getSelectedDino() {
  const filtered = getFilteredDinosaurs();
  return filtered.find((dino) => dino.id === state.selectedId) || filtered[0] || dinosaurs[0];
}

function getTaxonomyPath(dino) {
  return [dino.rootClade || "Dinosauria", dino.clade, dino.family].filter(Boolean).join(" / ");
}

function renderMetrics() {
  const filtered = getFilteredDinosaurs();
  const levels = [...new Set(filtered.map((dino) => dino.knowledgeLevel))].sort((a, b) => a - b);
  $("#metricSpecies").textContent = filtered.length;
  $("#metricClades").textContent = new Set(filtered.map((dino) => dino.clade)).size;
  $("#metricLevels").textContent = levels.length
    ? levels.length === 1
      ? `LV${levels[0]}`
      : `LV${levels[0]}-${levels[levels.length - 1]}`
    : "-";
  $("#metricImages").textContent = filtered.reduce((sum, dino) => sum + getGalleryItems(dino).length, 0);
}

function renderPeriodBands() {
  const layoutHeight = currentPhyloLayout.height || canvasSize.height;
  $("#periodBands").innerHTML = eras
    .map((era, index) => {
      const nextEra = eras[index + 1];
      const height = nextEra ? era.height : Math.max(era.height, layoutHeight - era.top);
      return `
        <section class="period-band ${era.id}" style="top: ${era.top}px; height: ${height}px;">
          <div class="period-label">
            <strong>${era.label}</strong>
            <span>${era.range}</span>
          </div>
        </section>
      `;
    })
    .join("");
}

function getNodeWidth(node) {
  return node.type === "group" ? 126 : 132;
}

function getNodeHeight() {
  return 64;
}

