function hexToRgb(hex) {
  const value = String(hex || "").replace("#", "").trim();
  if (!/^[0-9a-f]{6}$/i.test(value)) return null;
  return {
    r: parseInt(value.slice(0, 2), 16),
    g: parseInt(value.slice(2, 4), 16),
    b: parseInt(value.slice(4, 6), 16),
  };
}

function darkenRgb(rgb, amount = 34) {
  return {
    r: Math.max(12, rgb.r - amount),
    g: Math.max(16, rgb.g - amount),
    b: Math.max(20, rgb.b - amount),
  };
}

function rgbaFromHex(hex, alpha) {
  const rgb = hexToRgb(hex);
  if (!rgb) return `rgba(230, 196, 106, ${alpha})`;
  return `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${alpha})`;
}

function getTaxonPalette(dino) {
  const fallbackByFamily = {
    Ceratopsidae: { accent: "#55d6be", bg: "rgba(18, 48, 49, 0.86)", border: "rgba(85, 214, 190, 0.34)" },
    Tyrannosauridae: { accent: "#ff8e72", bg: "rgba(65, 34, 26, 0.86)", border: "rgba(255, 142, 114, 0.34)" },
    Spinosauridae: { accent: "#6cb9ff", bg: "rgba(27, 48, 68, 0.86)", border: "rgba(108, 185, 255, 0.34)" },
    Diplodocidae: { accent: "#9bd66f", bg: "rgba(38, 57, 31, 0.86)", border: "rgba(155, 214, 111, 0.34)" },
    Dromaeosauridae: { accent: "#d88cff", bg: "rgba(52, 36, 64, 0.86)", border: "rgba(216, 140, 255, 0.34)" },
    Alvarezsauridae: { accent: "#2ec7c9", bg: "rgba(28, 38, 45, 0.86)", border: "rgba(46, 199, 201, 0.34)" },
    Avimimidae: { accent: "#b58cff", bg: "rgba(43, 35, 55, 0.86)", border: "rgba(181, 140, 255, 0.34)" },
    Oviraptoridae: { accent: "#6bd28d", bg: "rgba(31, 45, 38, 0.86)", border: "rgba(107, 210, 141, 0.34)" },
    Caenagnathidae: { accent: "#d0a11e", bg: "rgba(37, 43, 34, 0.86)", border: "rgba(208, 161, 30, 0.34)" },
    Ornithomimidae: { accent: "#64b7d8", bg: "rgba(28, 48, 58, 0.86)", border: "rgba(100, 183, 216, 0.34)" },
    Therizinosauridae: { accent: "#d94a45", bg: "rgba(47, 35, 43, 0.86)", border: "rgba(217, 74, 69, 0.34)" },
    Hadrosauridae: { accent: "#e1783f", bg: "rgba(40, 53, 35, 0.86)", border: "rgba(225, 120, 63, 0.34)" },
  };
  const directPalette = taxonPaletteAccents[dino.id];
  if (directPalette) return directPalette;

  const swatches = taxonPaletteSwatches[dino.id];
  if (swatches?.length) {
    const accent = swatches[0];
    const anchor = hexToRgb(swatches[1] || accent) || hexToRgb(accent);
    const bg = anchor ? darkenRgb(anchor, 18) : { r: 38, g: 43, b: 48 };
    return {
      accent,
      bg: `rgba(${bg.r}, ${bg.g}, ${bg.b}, 0.9)`,
      border: rgbaFromHex(accent, 0.46),
    };
  }

  return fallbackByFamily[dino.family] || {
    accent: "#e6c46a",
    bg: "rgba(38, 43, 48, 0.86)",
    border: "rgba(230, 196, 106, 0.3)",
  };
}

function getDinoPaletteStyle(dino) {
  const palette = getTaxonPalette(dino);
  const swatches = getDinoPaletteSwatches(dino);
  const wash = rgbaFromHex(swatches[0], 0.28);
  const washAlt = rgbaFromHex(swatches[2] || swatches[1] || swatches[0], 0.2);
  return `--taxon-accent: ${palette.accent}; --taxon-bg: ${palette.bg}; --taxon-border: ${palette.border}; --taxon-wash: ${wash}; --taxon-wash-alt: ${washAlt};`;
}

function getDinoPaletteSwatches(dino) {
  const basePalette = getTaxonPalette(dino).accent;
  return taxonPaletteSwatches[dino.id] || [basePalette, "#3e4a46", "#9fbf8d", "#d8bd79"];
}

function renderDinoPaletteSwatches(dino, className = "palette-strip") {
  const swatches = getDinoPaletteSwatches(dino);
  return `
    <div class="${className}" aria-label="\uc885\ubcc4 \uc0c9 \ubc30\ub9ac\uc5d0\uc774\uc158">
      ${swatches
        .map((color) => `<span class="palette-swatch" style="background: ${color};" title="${color}"></span>`)
        .join("")}
    </div>
  `;
}

const phyloAutoLayouts = {
  "cretaceous-theropoda": {
    columns: 6,
    baseX: 720,
    yOffset: 72,
    sort: [
      "Tyrannosauridae",
      "Spinosauridae",
      "Ornithomimidae",
      "Therizinosauridae",
      "Alvarezsauridae",
      "Avimimidae",
      "Oviraptoridae",
      "Caenagnathidae",
      "Caudipterygidae",
      "Dromaeosauridae",
      "Troodontidae",
    ],
  },
  ornithopoda: {
    columns: 3,
    baseX: 1080,
    yOffset: 72,
    sort: ["Hadrosauridae", "Dryosauridae"],
  },
  ceratopsia: {
    columns: 5,
    baseX: 560,
    yOffset: 88,
    sort: [
      "Psittacosauridae",
      "Protoceratopsidae",
      "Leptoceratopsidae",
      "Ceratopsidae",
    ],
  },
  "jurassic-sauropoda": { columns: 3, baseX: 1040, yOffset: 82 },
  "jurassic-theropoda": { columns: 3, baseX: 1040, yOffset: 82 },
};

function getAutoPhyloColumns(parentId) {
  return phyloAutoLayouts[parentId]?.columns || 2;
}

function getPhyloFamilySortIndex(parentId, family) {
  const familyOrder = phyloAutoLayouts[parentId]?.sort || [];
  const index = familyOrder.indexOf(family);
  return index === -1 ? familyOrder.length + 1 : index;
}

function compareAutoPhyloDinos(parentId) {
  return (a, b) =>
    getPhyloFamilySortIndex(parentId, a.family) - getPhyloFamilySortIndex(parentId, b.family) ||
    a.family.localeCompare(b.family) ||
    a.name.localeCompare(b.name);
}

function getAutoPhyloSlot(parent, siblingCount) {
  const layout = phyloAutoLayouts[parent.id] || {};
  const nodeWidth = getNodeWidth({ type: "taxon" });
  const columnGap = 12;
  const rowGap = 12;
  const maxColumns = Math.max(
    1,
    Math.floor((canvasSize.width - 96 + columnGap) / (nodeWidth + columnGap)),
  );
  const columns = Math.min(getAutoPhyloColumns(parent.id), maxColumns);
  const blockWidth = columns * nodeWidth + (columns - 1) * columnGap;
  const preferredBaseX = layout.baseX ?? parent.x + 300;
  const baseX = Math.max(
    48,
    Math.min(preferredBaseX, canvasSize.width - blockWidth - 48),
  );
  const row = Math.floor(siblingCount / columns);
  const column = siblingCount % columns;
  return {
    x: baseX + column * (nodeWidth + columnGap),
    y: parent.y + (layout.yOffset || 90) + row * (getNodeHeight() + rowGap),
  };
}

function getKnownPhyloChildCount(parentId, nodes, edges) {
  const knownChildren = new Set(edges.filter(([from]) => from === parentId).map(([, to]) => to));
  nodes.forEach((node) => {
    if (node.parentId === parentId) knownChildren.add(node.id);
  });
  return [...knownChildren].filter((id) => {
    const node = nodes.find((candidate) => candidate.id === id);
    return node?.type === "taxon";
  }).length;
}

function inferPhyloParent(dino) {
  if (dino.clade === "Theropoda") {
    if (dino.era === "cretaceous") return "cretaceous-theropoda";
    if (dino.era === "jurassic") return "jurassic-theropoda";
    return "theropoda";
  }
  if (dino.clade === "Sauropodomorpha") {
    return dino.era === "jurassic" ? "jurassic-sauropoda" : "sauropodomorpha";
  }
  if (dino.family === "Hadrosauridae" || dino.clade === "Ornithopoda") return "ornithopoda";
  if (dino.family === "Ceratopsidae" || dino.clade === "Ceratopsia") return "ceratopsia";
  if (dino.family === "Pachycephalosauridae" || dino.clade === "Pachycephalosauria") {
    return "pachycephalosauria";
  }
  if (dino.family === "Ankylosauridae" || dino.clade === "Ankylosauria") return "ankylosauria";
  if (dino.family === "Stegosauridae" || dino.clade === "Thyreophora") return "thyreophora";
  return "ornithischia";
}

function getAugmentedPhyloData() {
  const nodes = phyloNodes.map((node) => ({ ...node }));
  const edges = phyloEdges.map(([from, to]) => [from, to]);
  const nodeMap = new Map(nodes.map((node) => [node.id, node]));
  const pendingByParent = new Map();

  dinosaurs.forEach((dino) => {
    if (nodeMap.has(dino.id)) return;
    const parentId = inferPhyloParent(dino);
    if (!pendingByParent.has(parentId)) pendingByParent.set(parentId, []);
    pendingByParent.get(parentId).push(dino);
  });

  pendingByParent.forEach((pendingDinos, parentId) => {
    const parent = nodeMap.get(parentId) || nodeMap.get("dinosauria");
    const siblingCount = getKnownPhyloChildCount(parent.id, nodes, edges);
    pendingDinos.sort(compareAutoPhyloDinos(parent.id)).forEach((dino, index) => {
      const slot = getAutoPhyloSlot(parent, siblingCount + index);
      const node = {
        id: dino.id,
        type: "taxon",
        speciesId: dino.id,
        x: slot.x,
        y: slot.y,
        autoLayout: true,
        parentId: parent.id,
      };
      nodes.push(node);
      nodeMap.set(node.id, node);
      if (!edges.some(([from, to]) => from === parent.id && to === node.id)) {
        edges.push([parent.id, node.id]);
      }
    });
  });

  return { nodes, edges };
}

function rectanglesOverlap(a, b, gap = 16) {
  return !(
    a.x + a.width + gap <= b.x ||
    b.x + b.width + gap <= a.x ||
    a.y + a.height + gap <= b.y ||
    b.y + b.height + gap <= a.y
  );
}

function resolvePhyloNodeCollisions(nodes, filteredIds) {
  const displayNodes = nodes.filter(
    (node) => node.type !== "taxon" || filteredIds.has(node.speciesId),
  );
  const sortedNodes = [...displayNodes].sort((a, b) => a.y - b.y || a.x - b.x);
  const rowGap = 8;
  let moved = true;
  let guard = 0;

  while (moved && guard < 100) {
    moved = false;
    guard += 1;
    for (let i = 0; i < sortedNodes.length; i += 1) {
      const a = sortedNodes[i];
      const rectA = {
        x: a.x,
        y: a.y,
        width: getNodeWidth(a),
        height: getNodeHeight(),
      };
      for (let j = i + 1; j < sortedNodes.length; j += 1) {
        const b = sortedNodes[j];
        const rectB = {
          x: b.x,
          y: b.y,
          width: getNodeWidth(b),
          height: getNodeHeight(),
        };
        if (!rectanglesOverlap(rectA, rectB, rowGap)) continue;
        const pushBy = rectA.y + rectA.height + rowGap - b.y;
        b.y += pushBy;
        moved = true;
      }
    }
    sortedNodes.sort((a, b) => a.y - b.y || a.x - b.x);
  }

  return nodes;
}

const phyloEraPackLayouts = {
  triassic: { columns: 5, baseX: 820, topPad: 78 },
  jurassic: { columns: 5, baseX: 480, topPad: 46 },
  cretaceous: { columns: 7, baseX: 280, topPad: 42 },
};

const phyloEraCladeOrder = [
  "Theropoda",
  "Sauropodomorpha",
  "Ornithopoda",
  "Ceratopsia",
  "Ankylosauria",
  "Pachycephalosauria",
  "Thyreophora",
];

function getPhyloEraBand(eraId) {
  return eras.find((era) => era.id === eraId);
}

function getPhyloCladeOrderIndex(clade) {
  const index = phyloEraCladeOrder.indexOf(clade);
  return index === -1 ? phyloEraCladeOrder.length : index;
}

function comparePhyloEraTaxa(a, b) {
  const dinoA = getDinoById(a.speciesId);
  const dinoB = getDinoById(b.speciesId);
  if (!dinoA || !dinoB) return a.id.localeCompare(b.id);
  return (
    getPhyloCladeOrderIndex(dinoA.clade) - getPhyloCladeOrderIndex(dinoB.clade) ||
    dinoA.clade.localeCompare(dinoB.clade) ||
    dinoA.family.localeCompare(dinoB.family) ||
    dinoA.name.localeCompare(dinoB.name) ||
    a.id.localeCompare(b.id)
  );
}

function interleavePhyloEraTaxa(taxa) {
  const buckets = new Map();

  taxa
    .slice()
    .sort(comparePhyloEraTaxa)
    .forEach((node) => {
      const clade = getDinoById(node.speciesId)?.clade || "other";
      if (!buckets.has(clade)) buckets.set(clade, []);
      buckets.get(clade).push(node);
    });

  const clades = [...buckets.keys()].sort(
    (left, right) => getPhyloCladeOrderIndex(left) - getPhyloCladeOrderIndex(right) || left.localeCompare(right),
  );
  const ordered = [];

  while (ordered.length < taxa.length) {
    clades.forEach((clade) => {
      const next = buckets.get(clade)?.shift();
      if (next) ordered.push(next);
    });
  }

  return ordered;
}

function getEraPackColumns(taxaCount, layout, era) {
  const nodeWidth = getNodeWidth({ type: "taxon" });
  const nodeHeight = getNodeHeight();
  const columnGap = 12;
  const rowGap = 8;
  const maxColumns = Math.max(
    1,
    Math.floor((canvasSize.width - layout.baseX - 48 + columnGap) / (nodeWidth + columnGap)),
  );
  let columns = Math.min(Math.max(1, layout.columns), maxColumns, taxaCount);
  const maxUsableColumns = Math.min(maxColumns, taxaCount);
  const usableHeight = Math.max(nodeHeight, era.height - layout.topPad - 18);

  while (columns < maxUsableColumns) {
    const rows = Math.ceil(taxaCount / columns);
    const totalHeight = rows * nodeHeight + Math.max(0, rows - 1) * rowGap;
    if (totalHeight <= usableHeight) break;
    columns += 1;
  }

  return columns;
}

function packTaxaIntoEraBands(nodes) {
  const nodeWidth = getNodeWidth({ type: "taxon" });
  const nodeHeight = getNodeHeight();
  const columnGap = 12;
  const preferredRowGap = 8;
  const taxaByEra = new Map();

  nodes.forEach((node) => {
    if (node.type !== "taxon") return;
    const eraId = getDinoById(node.speciesId)?.era;
    if (!eraId || !getPhyloEraBand(eraId)) return;
    if (!taxaByEra.has(eraId)) taxaByEra.set(eraId, []);
    taxaByEra.get(eraId).push(node);
  });

  taxaByEra.forEach((taxa, eraId) => {
    const era = getPhyloEraBand(eraId);
    const layout = phyloEraPackLayouts[eraId] || { columns: 4, baseX: 420, topPad: 42 };
    const columns = getEraPackColumns(taxa.length, layout, era);
    const rows = Math.ceil(taxa.length / columns);
    const usableHeight = Math.max(nodeHeight, era.height - layout.topPad - 18);
    const rowGap =
      rows > 1
        ? Math.max(2, Math.min(preferredRowGap, Math.floor((usableHeight - rows * nodeHeight) / (rows - 1))))
        : 0;
    const top = era.top + layout.topPad;

    interleavePhyloEraTaxa(taxa).forEach((node, index) => {
      const row = Math.floor(index / columns);
      const column = index % columns;
      node.x = layout.baseX + column * (nodeWidth + columnGap);
      node.y = Math.min(
        era.top + era.height - nodeHeight - 18,
        top + row * (nodeHeight + rowGap),
      );
    });
  });

  return nodes;
}

function buildPhyloLayout() {
  const { nodes, edges } = getAugmentedPhyloData();
  const laidOutNodes = packTaxaIntoEraBands(nodes);
  const maxX = laidOutNodes.reduce(
    (max, node) => Math.max(max, node.x + getNodeWidth(node) + 48),
    0,
  );
  const maxY = laidOutNodes.reduce(
    (max, node) => Math.max(max, node.y + getNodeHeight() + 48),
    0,
  );
  return {
    nodes: laidOutNodes,
    edges,
    nodeMap: new Map(laidOutNodes.map((node) => [node.id, node])),
    width: Math.ceil(Math.max(1600, maxX)),
    height: Math.ceil(Math.max(canvasSize.height, maxY)),
  };
}

function applyPhyloCanvasSize() {
  const canvas = $("#phyloCanvas");
  const lines = $("#treeLines");
  if (!canvas || !lines) return;
  canvas.style.width = `${currentPhyloLayout.width}px`;
  canvas.style.height = `${currentPhyloLayout.height}px`;
  lines.setAttribute("viewBox", `0 0 ${currentPhyloLayout.width} ${currentPhyloLayout.height}`);
}

function getNodeCenter(id) {
  const node = currentPhyloLayout.nodeMap.get(id);
  return {
    x: node.x + getNodeWidth(node) / 2,
    y: node.y + getNodeHeight() / 2,
  };
}

function edgePath(fromId, toId) {
  const from = getNodeCenter(fromId);
  const to = getNodeCenter(toId);
  const midX = from.x + (to.x - from.x) * 0.54;
  return `M ${from.x} ${from.y} C ${midX} ${from.y}, ${midX} ${to.y}, ${to.x} ${to.y}`;
}

function collectActiveEdges(targetId, active = new Set()) {
  currentPhyloLayout.edges
    .filter(([, to]) => to === targetId)
    .forEach(([from, to]) => {
      active.add(`${from}:${to}`);
      collectActiveEdges(from, active);
    });
  return active;
}

function renderTreeLines() {
  const filteredIds = getFilteredIdSet();
  const activeEdges = collectActiveEdges(state.selectedId);
  $("#treeLines").innerHTML = currentPhyloLayout.edges
    .filter(([, to]) => {
      const targetNode = currentPhyloLayout.nodeMap.get(to);
      return targetNode.type !== "taxon" || filteredIds.has(targetNode.speciesId);
    })
    .map(([from, to]) => {
      const className = activeEdges.has(`${from}:${to}`) ? "tree-line active" : "tree-line";
      return `<path class="${className}" d="${edgePath(from, to)}"></path>`;
    })
    .join("");
}

function renderMapNodes() {
  const filteredIds = getFilteredIdSet();
  const focusSpeciesIds = getPhyloFocusSpeciesIds(state.phyloFocusId);
  $("#mapNodes").innerHTML = currentPhyloLayout.nodes
    .map((node) => {
      const isTaxon = node.type === "taxon";
      const dino = isTaxon ? getDinoById(node.speciesId) : null;
      const level = isTaxon ? getKnowledgeLevel(dino.knowledgeLevel) : null;
      const hidden = isTaxon && !filteredIds.has(node.speciesId);
      const active = isTaxon && state.selectedId === node.speciesId;
      const groupActive = !isTaxon && state.phyloFocusId === node.id;
      const focusMatched = isTaxon && focusSpeciesIds.has(node.speciesId);
      const focusDimmed = isTaxon && focusSpeciesIds.size > 0 && !focusMatched;
      const paletteStyle = isTaxon ? `${getDinoPaletteStyle(dino)} ` : "";
      const classes = [
        "map-node",
        node.type,
        hidden ? "hidden-by-filter" : "",
        active ? "active" : "",
        groupActive ? "active" : "",
        focusMatched ? "focus-matched" : "",
        focusDimmed ? "focus-dimmed" : "",
      ]
        .filter(Boolean)
        .join(" ");
      const content = isTaxon
        ? `
          <span class="node-kind">${dino.period}</span>
          <strong>${dino.koreanName}</strong>
          <div class="node-meta">
            <span>${dino.name} / ${dino.family}</span>
            <span class="level-badge level-${dino.knowledgeLevel}">${level.short}</span>
          </div>
          ${renderDinoPaletteSwatches(dino, "palette-strip node-palette")}
        `
        : `
          <span class="node-kind">clade</span>
          <strong>${node.label}</strong>
          <span>${node.caption}</span>
        `;
      const tag = "button";
      const attrs = isTaxon
        ? `type="button" data-id="${node.speciesId}"`
        : `type="button" data-phylo-focus="${node.id}" aria-label="${node.label} 계통 강조"`;
      const renderedAttrs = isTaxon
        ? `type="button" data-id="${node.speciesId}"`
        : `type="button" data-phylo-focus="${node.id}" aria-label="${node.label} clade focus"`;
      return `
        <${tag} class="${classes}" ${renderedAttrs} style="${paletteStyle}left: ${node.x}px; top: ${node.y}px;">
          ${content}
        </${tag}>
      `;
    })
    .join("");

}

function getPhyloFocusSpeciesIds(focusId) {
  if (!focusId || !currentPhyloLayout?.nodeMap?.has(focusId)) return new Set();
  const ids = new Set();
  const queue = [focusId];
  const visited = new Set();

  while (queue.length) {
    const id = queue.shift();
    if (visited.has(id)) continue;
    visited.add(id);
    const node = currentPhyloLayout.nodeMap.get(id);
    if (node?.type === "taxon" && node.speciesId) {
      ids.add(node.speciesId);
    }
    currentPhyloLayout.edges.forEach(([from, to]) => {
      if (from === id) queue.push(to);
    });
  }

  return ids;
}

function applyPhyloFocusHighlight() {
  const focusSpeciesIds = getPhyloFocusSpeciesIds(state.phyloFocusId);

  $$(".map-node.group").forEach((node) => {
    node.classList.toggle("active", node.dataset.phyloFocus === state.phyloFocusId);
  });

  $$(".map-node.taxon").forEach((node) => {
    const matched = focusSpeciesIds.has(node.dataset.id);
    node.classList.remove("focus-matched", "focus-dimmed");
    if (focusSpeciesIds.size > 0) {
      node.classList.add(matched ? "focus-matched" : "focus-dimmed");
    }
  });

  $$(".dino-card").forEach((card) => {
    const matched = focusSpeciesIds.has(card.dataset.id);
    card.classList.remove("focus-matched", "focus-dimmed");
    if (focusSpeciesIds.size > 0) {
      card.classList.add(matched ? "focus-matched" : "focus-dimmed");
    }
  });
}

function applyMapTransform({ updateZoomLabel = true } = {}) {
  const canvas = $("#phyloCanvas");
  if (!canvas) return;
  canvas.style.transform = `translate3d(${state.map.x}px, ${state.map.y}px, 0) scale(${state.map.scale})`;
  if (updateZoomLabel) $("#zoomLevel").textContent = `${Math.round(state.map.scale * 100)}%`;
}

function scheduleMapPanTransform() {
  if (state.map.transformFrame) return;
  state.map.transformFrame = requestAnimationFrame(() => {
    state.map.transformFrame = 0;
    applyMapTransform({ updateZoomLabel: false });
  });
}

function flushMapPanTransform() {
  if (state.map.transformFrame) {
    cancelAnimationFrame(state.map.transformFrame);
    state.map.transformFrame = 0;
  }
  applyMapTransform({ updateZoomLabel: false });
}

function clampScale(scale) {
  return Math.max(0.38, Math.min(1.8, scale));
}

function fitMapToViewport() {
  const viewport = $("#mapViewport");
  if (!viewport) return;
  const mapWidth = currentPhyloLayout.width || canvasSize.width;
  const mapHeight = currentPhyloLayout.height || canvasSize.height;
  const widthScale = (viewport.clientWidth - 36) / mapWidth;
  const heightScale = (viewport.clientHeight - 36) / mapHeight;
  const scale = clampScale(Math.min(widthScale, heightScale, 0.72));
  state.map.scale = scale;
  state.map.x = Math.round((viewport.clientWidth - mapWidth * scale) / 2);
  state.map.y = Math.round((viewport.clientHeight - mapHeight * scale) / 2);
  applyMapTransform();
}

function zoomMap(nextScale, originX, originY) {
  const viewport = $("#mapViewport");
  const rect = viewport.getBoundingClientRect();
  const scale = clampScale(nextScale);
  const px = originX ?? rect.left + rect.width / 2;
  const py = originY ?? rect.top + rect.height / 2;
  const mapX = (px - rect.left - state.map.x) / state.map.scale;
  const mapY = (py - rect.top - state.map.y) / state.map.scale;
  state.map.scale = scale;
  state.map.x = px - rect.left - mapX * scale;
  state.map.y = py - rect.top - mapY * scale;
  applyMapTransform();
}

function renderPhyloMap() {
  const selected = getSelectedDino();
  state.selectedId = selected.id;
  currentPhyloLayout = buildPhyloLayout();
  applyPhyloCanvasSize();
  renderPeriodBands();
  renderTreeLines();
  renderMapNodes();
  applyMapTransform();
}

function renderDetail() {
  const dino = getSelectedDino();
  state.selectedId = dino.id;
  const level = getKnowledgeLevel(dino.knowledgeLevel);
  const galleryItems = getGalleryItems(dino);
  state.galleryIndex = Math.min(state.galleryIndex, galleryItems.length - 1);
  const featureRows = Object.entries(dino.features)
    .map(([key, value]) => `<div class="feature-row"><span>${key}</span><strong>${value}</strong></div>`)
    .join("");
  const visualProfilePanel = renderVisualVariationSummary(getVisualVariationProfile(dino), dino);
  const primaryImage = getPrimaryImage(dino);
  const slides = galleryItems
    .map(
      (item, index) => `
        <article class="gallery-slide" aria-label="${item.title}">
          <button class="gallery-image ${item.variant} ${item.src ? "has-real-image can-zoom" : ""}" data-lightbox-context="gallery" data-gallery-index="${index}" type="button"${imageStyle(item)} ${item.src ? "" : "disabled"}>
            <span class="image-label">${item.kind}</span>
          </button>
          <div class="gallery-copy">
            <div>
              <p class="eyebrow">${item.kind}</p>
              <h4>${item.title}</h4>
            </div>
            <p>${item.body}</p>
            <span class="source-note">${item.source}</span>
          </div>
        </article>
      `,
    )
    .join("");
  const dots = galleryItems
    .map(
      (_, index) => `
        <button class="gallery-dot ${index === state.galleryIndex ? "active" : ""}" data-gallery-index="${index}" type="button" aria-label="이미지 ${index + 1}"></button>
      `,
    )
    .join("");

  $("#detailPanel").innerHTML = `
    <div class="inspector-header">
      <button class="dummy-image ${primaryImage ? "has-real-image can-zoom" : ""}" data-lightbox-context="primary" type="button" aria-label="Dinosaur image preview"${imageStyle(primaryImage)} ${primaryImage ? "" : "disabled"}>
        <span class="image-label">${galleryItems.length} views</span>
      </button>
      <div class="inspector-title">
        <p class="eyebrow">${dino.clade} / ${dino.family}</p>
        <h3>${dino.koreanName}</h3>
        <p class="summary">${dino.name}</p>
      </div>
    </div>
    <section class="image-gallery" aria-label="Image comparison gallery">
      <div class="gallery-topline">
        <span>${state.galleryIndex + 1} / ${galleryItems.length}</span>
        <div class="gallery-buttons">
          <button class="gallery-nav icon-button" data-gallery-action="prev" type="button" aria-label="이전 이미지"><span class="button-icon icon-chevron-left" aria-hidden="true"></span></button>
          <button class="gallery-nav icon-button" data-gallery-action="next" type="button" aria-label="다음 이미지"><span class="button-icon icon-chevron-right" aria-hidden="true"></span></button>
        </div>
      </div>
      <div class="gallery-viewport">
        <div class="gallery-track" style="transform: translateX(-${state.galleryIndex * 100}%);">
          ${slides}
        </div>
      </div>
      <div class="gallery-dots">${dots}</div>
    </section>
    ${visualProfilePanel}
    <div class="kicker-row">
      <span class="level-badge level-${dino.knowledgeLevel}">${level.short} · ${level.label}</span>
      <span class="pill">${dino.period}</span>
      <span class="pill">${dino.diet}</span>
      <span class="pill">${dino.region}</span>
    </div>
    <p class="summary">${dino.summary}</p>
    <div class="fact-grid">
      <div class="fact"><span>분류 경로</span><strong>${getTaxonomyPath(dino)}</strong></div>
      <div class="fact"><span>예상 길이</span><strong>${dino.length.toFixed(1)} m</strong></div>
      <div class="fact"><span>출처 메모</span><strong>${dino.sources.join(", ")}</strong></div>
      <div class="fact"><span>퀴즈 연결</span><strong>${level.description}</strong></div>
    </div>
    <div class="feature-list">${featureRows}</div>
  `;
  bindGalleryEvents(dino, galleryItems);
}

function moveGallery(delta, total) {
  state.galleryIndex = (state.galleryIndex + delta + total) % total;
  renderDetail();
}

function bindGalleryEvents(dino, galleryItems = []) {
  const total = galleryItems.length;
  $$(".gallery-nav").forEach((button) => {
    button.addEventListener("click", () => {
      moveGallery(button.dataset.galleryAction === "next" ? 1 : -1, total);
    });
  });

  $$(".gallery-dot").forEach((button) => {
    button.addEventListener("click", () => {
      state.galleryIndex = Number(button.dataset.galleryIndex);
      renderDetail();
    });
  });

  $$("[data-lightbox-context='gallery']").forEach((button) => {
    button.addEventListener("click", () => {
      const item = galleryItems[Number(button.dataset.galleryIndex)];
      if (!item?.src) return;
      openLightbox(galleryItems, Number(button.dataset.galleryIndex));
    });
  });

  $$("[data-lightbox-context='primary']").forEach((button) => {
    button.addEventListener("click", () => {
      const primaryImage = getPrimaryImage(dino);
      if (primaryImage?.src) openDinoGalleryLightbox(dino, primaryImage);
    });
  });

  const viewport = $(".gallery-viewport");
  if (!viewport) return;

  viewport.addEventListener("pointerdown", (event) => {
    if (event.target.closest("[data-lightbox-context]")) return;
    state.galleryDragStart = event.clientX;
    viewport.setPointerCapture(event.pointerId);
  });

  viewport.addEventListener("pointerup", (event) => {
    if (event.target.closest("[data-lightbox-context]")) return;
    const diff = event.clientX - state.galleryDragStart;
    if (Math.abs(diff) > 38) {
      moveGallery(diff < 0 ? 1 : -1, total);
    }
    if (viewport.hasPointerCapture(event.pointerId)) {
      viewport.releasePointerCapture(event.pointerId);
    }
  });
}

function getRecentImageUpdateRank(dino) {
  return recentImageUpdateRanks.get(dino.id) || 0;
}

function compareByRecentImageUpdate(a, b) {
  const rankDelta = getRecentImageUpdateRank(b) - getRecentImageUpdateRank(a);
  if (rankDelta) return rankDelta;
  return a.koreanName.localeCompare(b.koreanName, "ko");
}

function compareByReviewQueueOrder(a, b, filterKey = state.reviewQueueKindFilter, sortKey = state.reviewSort) {
  const countDelta = getReviewCandidateCountByFilter(b, filterKey) - getReviewCandidateCountByFilter(a, filterKey);
  const generatedAtDelta = getLatestReviewCandidateTimestamp(b) - getLatestReviewCandidateTimestamp(a);
  const rankDelta = getRecentImageUpdateRank(b) - getRecentImageUpdateRank(a);
  if (sortKey === "candidates" && countDelta) return countDelta;
  if (sortKey === "name") return a.koreanName.localeCompare(b.koreanName, "ko");
  if (sortKey === "level") {
    return a.knowledgeLevel - b.knowledgeLevel || a.koreanName.localeCompare(b.koreanName, "ko");
  }
  if (generatedAtDelta) return generatedAtDelta;
  if (rankDelta) return rankDelta;
  if (countDelta) return countDelta;
  return a.koreanName.localeCompare(b.koreanName, "ko");
}

function sortDinosaurs(list) {
  return [...list].sort((a, b) => {
    if (state.sort === "updated") return compareByRecentImageUpdate(a, b);
    if (state.sort === "size") return b.length - a.length;
    if (state.sort === "level") return a.knowledgeLevel - b.knowledgeLevel || a.koreanName.localeCompare(b.koreanName, "ko");
    if (state.sort === "period") return a.period.localeCompare(b.period, "ko");
    if (state.sort === "name") return a.koreanName.localeCompare(b.koreanName, "ko");
    return compareByRecentImageUpdate(a, b);
  });
}

function renderCatalog() {
  const grid = $("#catalogGrid");
  const items = sortDinosaurs(getFilteredDinosaurs());
  const focusSpeciesIds = getPhyloFocusSpeciesIds(state.phyloFocusId);
  grid.innerHTML = items
    .map(
      (dino) => {
        const level = getKnowledgeLevel(dino.knowledgeLevel);
        const primaryImage = getPrimaryImage(dino);
        const focusMatched = focusSpeciesIds.has(dino.id);
        const focusDimmed = focusSpeciesIds.size > 0 && !focusMatched;
        return `
        <article class="dino-card ${focusMatched ? "focus-matched" : ""} ${focusDimmed ? "focus-dimmed" : ""}" data-id="${dino.id}" tabindex="0" style="${getDinoPaletteStyle(dino)}">
          <div class="dummy-image ${primaryImage ? "has-real-image can-zoom" : ""}" data-card-image-zoom="${dino.id}" role="button" tabindex="0"${imageStyle(primaryImage)}>
            <span class="image-label">${dino.name}</span>
          </div>
          <div class="card-body">
            <div>
              <p class="eyebrow">${dino.family}</p>
              <h4>${dino.koreanName}</h4>
            </div>
            ${renderDinoPaletteSwatches(dino, "palette-strip compact")}
            <div class="kicker-row">
              <span class="level-badge level-${dino.knowledgeLevel}">${level.short}</span>
              <span class="pill">${dino.period}</span>
              <span class="pill">${dino.diet}</span>
            </div>
            <p>${dino.summary}</p>
          </div>
        </article>
      `;
      },
    )
    .join("");

  $$(".dino-card").forEach((card) => {
    const imageZoom = card.querySelector("[data-card-image-zoom]");
    if (imageZoom) {
      const openImage = (event) => {
        event.stopPropagation();
        const dino = getDinoById(card.dataset.id);
        const primaryImage = dino ? getPrimaryImage(dino) : null;
        if (dino && primaryImage?.src) openDinoGalleryLightbox(dino, primaryImage);
      };
      imageZoom.addEventListener("click", openImage);
      imageZoom.addEventListener("keydown", (event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          openImage(event);
        }
      });
    }
    const open = () => {
      state.selectedId = card.dataset.id;
      state.phyloFocusId = "";
      state.galleryIndex = 0;
      setView("atlas");
    };
    card.addEventListener("click", open);
    card.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") open();
    });
  });
}

function statusClass(status) {
  if (status === "승인") return "ready";
  if (status === "검수중") return "pending";
  return "flagged";
}

const candidateKindGroups = {
  all: () => true,
  usable: (item) => item.kind === "review hold",
  representative: (item) =>
    ["primary generated", "primary structure reference", "count-level pass"].includes(item.kind),
  review: (item) => item.kind === "anatomy review" || item.kind === "structure reference",
  diagnostic: (item) => item.kind === "diagnostic only" || item.kind === "reject reference",
};

const candidateKindFilterLabels = {
  all: "전체",
  representative: "대표권",
  review: "검토",
  diagnostic: "진단/실패",
};

