function getGenerationRouteGuide(dino) {
  return generationRouteGuides[dino.id];
}

function getGenerationRouteClipboardText(dino) {
  const guide = getGenerationRouteGuide(dino);
  const variation = getVisualVariationProfile(dino);
  if (!guide && !variation) return "";
  const lines = [
    `${dino.name} generation route`,
  ];
  if (guide) {
    lines.push(
      `Focus: ${guide.focus}`,
      `Route: ${guide.route}`,
      `Control guide: ${guide.control}`,
      `Pass setup: ${guide.pass}`,
      `Reject: ${guide.reject}`,
    );
  }
  if (variation) {
    lines.push(
      `Color: ${variation.color}`,
      `Pattern: ${variation.pattern}`,
      `Texture: ${variation.texture}`,
      `Anatomy marker: ${variation.anatomy}`,
      `Avoid: ${variation.avoid}`,
    );
  }
  return lines.join("\n");
}

function renderVisualVariationGuide(profile, dino = null) {
  if (!profile) return "";
  const items = [
    [visualVariationLabels.color, profile.color],
    [visualVariationLabels.pattern, profile.pattern],
    [visualVariationLabels.texture, profile.texture],
    [visualVariationLabels.anatomy, profile.anatomy],
    [visualVariationLabels.avoid, profile.avoid],
  ];
  return `
    <div class="visual-variation-gate">
      <div>
        <p class="eyebrow">${visualVariationLabels.eyebrow}</p>
        <h4>${visualVariationLabels.title}</h4>
        ${dino ? renderDinoPaletteSwatches(dino, "palette-strip detail-palette") : ""}
      </div>
      <dl class="variation-stat-grid">
        ${items
          .map(
            ([label, value]) => `
              <div>
                <dt>${label}</dt>
                <dd>${escapeHtml(value)}</dd>
              </div>
            `,
          )
          .join("")}
      </dl>
    </div>
  `;
}

function renderVisualVariationSummary(profile, dino = null) {
  return renderVisualVariationGuide(profile, dino);
}

function renderGenerationRouteGuide(guide) {
  if (!guide) return "";
  return `
    <div class="generation-route-gate">
      <div class="route-guide-copy">
        <div>
          <p class="eyebrow">${generationRouteLabels.eyebrow}</p>
          <h4>${generationRouteLabels.title}</h4>
        </div>
        <dl class="route-stat-grid">
          <div>
            <dt>${generationRouteLabels.focus}</dt>
            <dd>${escapeHtml(guide.focus)}</dd>
          </div>
          <div>
            <dt>Route</dt>
            <dd>${escapeHtml(guide.route)}</dd>
          </div>
          <div>
            <dt>${generationRouteLabels.pass}</dt>
            <dd>${escapeHtml(guide.pass)}</dd>
          </div>
          <div>
            <dt>${generationRouteLabels.reject}</dt>
            <dd>${escapeHtml(guide.reject)}</dd>
          </div>
        </dl>
        <button data-review-action="copy-route" type="button">${generationRouteLabels.copy}</button>
      </div>
      <div class="route-guide-visual">
        <div class="route-guide-thumb ${guide.control ? "has-real-image" : ""}"${imageStyle({ src: guide.control })}>
          <span class="image-label">${generationRouteLabels.control}</span>
        </div>
        <span class="source-note">${escapeHtml(guide.control)}</span>
      </div>
    </div>
  `;
}

function getReviewStatus(dino) {
  const primary = getPrimaryImage(dino);
  const selectedSource = getManualCandidateSource(dino);
  const decisionCounts = getCandidateReviewDecisionCounts(dino);
  if (selectedSource) return { label: "수동 선택", className: "ready" };
  if (decisionCounts.approved) return { label: "적합 후보", className: "ready" };
  if (decisionCounts.pending) return { label: "보류 후보", className: "pending" };
  if (!primary) return { label: "후보 없음", className: "flagged" };
  if (primary.kind === "diagnostic only") return { label: "대표 없음", className: "flagged" };
  if (primary.kind === "primary structure reference") return { label: "구조 기준", className: "pending" };
  if (primary.kind === "primary generated") return { label: "대표 후보", className: "ready" };
  if (primary.kind === "count-level pass") return { label: "검토 필요", className: "pending" };
  return { label: "보류", className: "pending" };
}

function getCandidateKindClass(kind) {
  if (kind === "diagnostic only" || kind === "reject reference") return "diagnostic";
  if (kind === "primary generated") return "ready";
  if (kind === "primary structure reference") return "structure";
  if (kind === "count-level pass") return "candidate";
  return "pending";
}

const internalReviewKinds = new Set([
  "diagnostic only",
  "reject reference",
  "structure reference",
  "primary structure reference",
]);

// Retain superseded review evidence on disk, but never surface user-rejected or obsolete candidates.
const retiredReviewCandidateSources = new Set([
  "assets/dinosaurs/velociraptor-mongoliensis-dune-plumage-variant-imagegen-v1.png",
  "assets/dinosaurs/ankylosaurus-magniventris-imagegen-v20-source-candidate.png",
  "assets/dinosaurs/ankylosaurus-magniventris-imagegen-v22-source-candidate.png",
  "assets/dinosaurs/ankylosaurus-magniventris-imagegen-v23-source-candidate.png",
  "assets/dinosaurs/ankylosaurus-magniventris-imagegen-v24-source-candidate.png",
  "assets/dinosaurs/ankylosaurus-magniventris-imagegen-v25-source-candidate.png",
  "assets/dinosaurs/ankylosaurus-magniventris-imagegen-v26-source-candidate.png",
  "assets/dinosaurs/ankylosaurus-magniventris-imagegen-v27-source-candidate.png",
  "assets/dinosaurs/ankylosaurus-magniventris-imagegen-v32-source-candidate.png",
  "assets/dinosaurs/ankylosaurus-magniventris-imagegen-v34-source-candidate.png",
  "assets/dinosaurs/ankylosaurus-magniventris-imagegen-v38-source-candidate.png",
  "assets/dinosaurs/ankylosaurus-magniventris-allfeet-lora-i2i-v18.png",
  "assets/dinosaurs/ankylosaurus-magniventris-imagegen-v42-source-candidate.png",
  "assets/dinosaurs/triceratops-horridus-frill-naturalized-v1.png",
]);

function isInternalReviewCandidate(item) {
  if (!item) return false;
  if (item.internalOnly) return true;
  if (internalReviewKinds.has(item.kind)) return true;
  if (retiredReviewCandidateSources.has(item.source) || retiredReviewCandidateSources.has(item.src)) {
    return true;
  }
  const searchable = `${item.title || ""} ${item.source || ""} ${item.src || ""}`.toLowerCase();
  if (/review[- ]?sheet|review[- ]?options|contact[- ]?sheet|crop(?:s| audit| gate)?|guide|manifest|comparison|diagnostic|rejected|검수\s*(?:시트|보드)?|크롭|가이드|매니페스트|비교\s*시트|진단|탈락/.test(searchable)) {
    return true;
  }
  return /(?:^|[-_/ ])mask(?:-v\d+)?(?:\.png)?(?:$|\s)/.test(searchable);
}

function getVisibleReviewCandidates(dino) {
  return getAllCandidates(dino).filter((item) => !isInternalReviewCandidate(item));
}

function getLatestReviewCandidateTimestamp(dino) {
  return getVisibleReviewCandidates(dino).reduce(
    (latest, item) => Math.max(latest, getCandidateGeneratedTimestamp(item)),
    0,
  );
}

function getFilteredReviewCandidates(candidates, filterKey = state.reviewCandidateKindFilter) {
  const matcher = candidateKindGroups[filterKey] || candidateKindGroups.all;
  return candidates.filter((item) => !isInternalReviewCandidate(item)).filter(matcher);
}

function getCandidatesByKindFilter(dino, filterKey = state.reviewCandidateKindFilter) {
  const matcher = candidateKindGroups[filterKey] || candidateKindGroups.all;
  return getVisibleReviewCandidates(dino).filter(matcher).sort(compareReviewCandidatesByLatest);
}

function getReviewCandidateCountByFilter(dino, filterKey = state.reviewQueueKindFilter) {
  return getCandidatesByKindFilter(dino, filterKey).length;
}

function sortReviewDinosaurs(list, filterKey = state.reviewQueueKindFilter, sortKey = state.reviewSort) {
  return [...list]
    .filter((dino) => getReviewCandidateCountByFilter(dino, filterKey) > 0)
    .sort((a, b) => compareByReviewQueueOrder(a, b, filterKey, sortKey));
}

function getTopReviewDino(filterKey = state.reviewQueueKindFilter, sortKey = state.reviewSort) {
  const sorted = sortReviewDinosaurs(dinosaurs, filterKey, sortKey);
  return sorted[0] || dinosaurs[0];
}

function getLightboxIndexForCandidate(items, candidateOrSource) {
  const source =
    typeof candidateOrSource === "string" ? candidateOrSource : getCandidateKey(candidateOrSource);
  if (!source) return -1;
  return getLightboxItems(items).findIndex((item) => item.source === source || item.src === source);
}

function getLightboxFilterForCandidate(item) {
  if (!item) return "usable";
  if (candidateKindGroups.review(item)) return "review";
  if (candidateKindGroups.diagnostic(item)) return "diagnostic";
  if (candidateKindGroups.representative(item)) return "representative";
  if (candidateKindGroups.usable(item)) return "usable";
  return "all";
}

function resolveCandidateForLightbox(dino, candidateOrSource) {
  if (!candidateOrSource || typeof candidateOrSource !== "string") return candidateOrSource;
  return getAllCandidates(dino).find((item) => {
    const key = getCandidateKey(item);
    return key === candidateOrSource || item.src === candidateOrSource || item.source === candidateOrSource;
  });
}

function openCandidateLightbox(dino, filterKey, candidateOrSource) {
  const clickedCandidate = resolveCandidateForLightbox(dino, candidateOrSource);
  const items = getCandidatesByKindFilter(dino, filterKey);
  const index = getLightboxIndexForCandidate(items, clickedCandidate || candidateOrSource);
  if (items.length && index >= 0) {
    openLightbox(items, index);
    return;
  }
  if (clickedCandidate?.src) {
    openLightbox([clickedCandidate], 0);
    return;
  }
  openLightbox(items, 0);
}

const candidateReviewDecisionLabels = {
  approved: { label: "적합", className: "approved" },
  pending: { label: "보류", className: "pending" },
  rejected: { label: "탈락", className: "rejected" },
};

function getCandidateReviewDecision(dino, source) {
  if (!source) return "";
  return candidateReviewDecisions[dino.id]?.[source] || "";
}

function getCandidateReviewDecisionMeta(decision) {
  return candidateReviewDecisionLabels[decision] || null;
}

function getCandidateReviewDecisionCounts(dino) {
  const counts = { approved: 0, pending: 0, rejected: 0 };
  getVisibleReviewCandidates(dino).forEach((item) => {
    const decision = getCandidateReviewDecision(dino, getCandidateKey(item));
    if (counts[decision] !== undefined) counts[decision] += 1;
  });
  return counts;
}

function setCandidateReviewDecision(dino, source, decision) {
  if (!source) return;
  const nextDecisions = {
    ...candidateReviewDecisions,
    [dino.id]: {
      ...(candidateReviewDecisions[dino.id] || {}),
    },
  };

  if (decision) {
    nextDecisions[dino.id][source] = decision;
  } else {
    delete nextDecisions[dino.id][source];
  }

  if (!Object.keys(nextDecisions[dino.id]).length) delete nextDecisions[dino.id];
  candidateReviewDecisions = nextDecisions;
  saveCandidateReviewDecisions();

  if (decision === "rejected" && manualCandidateSelections[dino.id] === source) {
    const nextSelections = { ...manualCandidateSelections };
    delete nextSelections[dino.id];
    manualCandidateSelections = nextSelections;
    saveManualCandidateSelections();
  }

  state.reviewPreviewSource = source;
  renderAll();
}

function getCuratedCandidateItems(dino) {
  return getVisibleReviewCandidates(dino).filter(candidateKindGroups.usable);
}

function buildReviewDataExport() {
  const taxa = {};
  dinosaurs.forEach((dino) => {
    const decisions = candidateReviewDecisions[dino.id] || {};
    const manualSource = manualCandidateSelections[dino.id] || "";
    const defaultPrimary = getCandidateKey(getPrimaryImage(dino)) || "";
    const candidates = getCuratedCandidateItems(dino).map((item) => {
      const source = getCandidateKey(item);
      return {
        source,
        title: item.title || "",
        kind: item.kind || "",
        decision: decisions[source] || "",
        selected: source === manualSource,
      };
    });

    taxa[dino.id] = {
      taxonId: dino.id,
      name: dino.name,
      koreanName: dino.koreanName,
      visualVariationProfile: getVisualVariationProfile(dino),
      defaultPrimary,
      selectedPrimary: manualSource || defaultPrimary,
      candidates,
      finalFolder: `assets/dinosaurs/curated/final-candidates/${dino.id}/`,
      referenceFolder: `assets/dinosaurs/curated/reference-library/${dino.id}/`,
    };
  });

  return {
    schema: "dino-atlas-review-decisions-v1",
    exportedAt: new Date().toISOString(),
    manualCandidateSelections,
    candidateReviewDecisions,
    taxa,
  };
}

function downloadReviewDataExport() {
  const data = buildReviewDataExport();
  const blob = new Blob([`${JSON.stringify(data, null, 2)}\n`], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = "dino-atlas-review-decisions.json";
  document.body.append(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

function setManualCandidateSelection(dino, source) {
  manualCandidateSelections = {
    ...manualCandidateSelections,
    [dino.id]: source,
  };
  saveManualCandidateSelections();
  state.selectedId = dino.id;
  state.reviewSelectedId = dino.id;
  state.reviewPreviewSource = source;
  state.galleryIndex = 0;
  renderAll();
}

function clearManualCandidateSelection(dino) {
  const nextSelections = { ...manualCandidateSelections };
  delete nextSelections[dino.id];
  manualCandidateSelections = nextSelections;
  saveManualCandidateSelections();
  state.reviewPreviewSource = "";
  state.galleryIndex = 0;
  renderAll();
}

function copyToClipboard(text) {
  fallbackCopyToClipboard(text);
}

function fallbackCopyToClipboard(text) {
  const input = document.createElement("textarea");
  input.value = text;
  document.body.append(input);
  input.select();
  document.execCommand("copy");
  input.remove();
}

function renderReview() {
  const reviewItems = sortReviewDinosaurs(dinosaurs, state.reviewQueueKindFilter, state.reviewSort);
  const selectedDino =
    reviewItems.find((dino) => dino.id === state.reviewSelectedId) ||
    getTopReviewDino(state.reviewQueueKindFilter, state.reviewSort);
  state.reviewSelectedId = selectedDino.id;
  const queueFilterButtons = Object.entries(candidateKindFilterLabelsForReview)
    .map(
      ([key, label]) => `
        <button class="${state.reviewQueueKindFilter === key ? "active" : ""}" data-review-queue-kind-filter="${key}" type="button">${label}</button>
      `,
    )
    .join("");
  const candidateFilterButtons = Object.entries(candidateKindFilterLabelsForReview)
    .map(
      ([key, label]) => `
        <button class="${state.reviewCandidateKindFilter === key ? "active" : ""}" data-review-candidate-kind-filter="${key}" type="button">${label}</button>
      `,
    )
    .join("");
  const sortOptions = Object.entries(reviewSortLabels)
    .map(
      ([key, label]) => `
        <option value="${key}"${state.reviewSort === key ? " selected" : ""}>${label}</option>
      `,
    )
    .join("");

  $("#reviewQueue").innerHTML = `
    <div class="review-queue-controls">
      <div class="segmented review-kind-filters" role="group" aria-label="Review candidate kind filter">
        ${queueFilterButtons}
      </div>
      <select data-review-sort aria-label="Sort review queue">
        ${sortOptions}
      </select>
    </div>
  ` + reviewItems
    .map((dino) => {
      const level = getKnowledgeLevel(dino.knowledgeLevel);
      const primaryImage = getPrimaryImage(dino);
      const candidates = getCandidatesByKindFilter(dino, state.reviewQueueKindFilter);
      const totalCandidates = getVisibleReviewCandidates(dino);
      const status = getReviewStatus(dino);
      const isActive = selectedDino.id === dino.id;
      const decisionCounts = getCandidateReviewDecisionCounts(dino);
      return `
        <button class="review-item ${isActive ? "active" : ""}" data-review-id="${dino.id}" type="button">
          <div class="dummy-image review-thumb ${primaryImage ? "has-real-image can-zoom" : ""}" data-review-thumb-zoom="${dino.id}"${imageStyle(primaryImage)}></div>
          <div class="review-meta">
            <h4>${dino.koreanName}</h4>
            <p>${level.short} ${level.label} · 필터 ${candidates.length}장 · 전체 ${totalCandidates.length}장 · 적합 ${decisionCounts.approved} · 보류 ${decisionCounts.pending} · 탈락 ${decisionCounts.rejected}</p>
            <span>${dino.name}</span>
          </div>
          <span class="status ${status.className}">${status.label}</span>
        </button>
      `;
    })
    .join("");

  const candidates = [...getAllCandidates(selectedDino)].sort(compareReviewCandidatesByLatest);
  const manualSource = getManualCandidateSource(selectedDino);
  const currentPrimary = getPrimaryImage(selectedDino);
  const filteredCandidates = getFilteredReviewCandidates(candidates, state.reviewCandidateKindFilter);
  const filteredCandidateKeys = new Set(filteredCandidates.map((item) => getCandidateKey(item)));
  const currentPrimaryKey = getCandidateKey(currentPrimary);
  const fallbackSource =
    (manualSource && filteredCandidateKeys.has(manualSource) && manualSource) ||
    (currentPrimaryKey && filteredCandidateKeys.has(currentPrimaryKey) && currentPrimaryKey) ||
    getCandidateKey(filteredCandidates[0]);
  const previewSource =
    state.reviewPreviewSource && filteredCandidateKeys.has(state.reviewPreviewSource)
      ? state.reviewPreviewSource
      : fallbackSource;
  const previewCandidate =
    filteredCandidates.find((item) => getCandidateKey(item) === previewSource) ||
    filteredCandidates[0];
  state.reviewPreviewSource = getCandidateKey(previewCandidate);

  const candidateLightboxItems = getLightboxItems(filteredCandidates);
  const getCandidateLightboxIndex = (item) =>
    item?.src
      ? candidateLightboxItems.findIndex(
          (lightboxItem) => lightboxItem.src === item.src && lightboxItem.title === item.title,
        )
      : -1;
  const checklist = getIdentityChecklist(selectedDino)
    .map((item) => `<li>${escapeHtml(item)}</li>`)
    .join("");
  const variationPanel = renderVisualVariationGuide(getVisualVariationProfile(selectedDino), selectedDino);
  const generationRoutePanel = renderGenerationRouteGuide(getGenerationRouteGuide(selectedDino));
  const candidateCards = filteredCandidates.length
    ? filteredCandidates
        .map((item) => {
          const key = getCandidateKey(item);
          const isPreview = key === getCandidateKey(previewCandidate);
          const isManual = key === manualSource;
          const kindClass = getCandidateKindClass(item.kind);
          const decision = getCandidateReviewDecision(selectedDino, key);
          const decisionMeta = getCandidateReviewDecisionMeta(decision);
          const lightboxIndex = getCandidateLightboxIndex(item);
          return `
            <article class="candidate-card ${isPreview ? "active" : ""} ${isManual ? "manual" : ""} ${decision ? `decision-${decision}` : ""}">
              <button class="candidate-thumb ${item.src ? "has-real-image can-zoom" : ""}" data-review-action="lightbox" data-lightbox-index="${lightboxIndex}" data-source="${escapeHtml(key)}" type="button"${imageStyle(item)} ${item.src ? "" : "disabled"}>
                <span class="image-label">${escapeHtml(item.kind)}</span>
              </button>
              <div class="candidate-copy">
                <div class="candidate-title-row">
                  <span class="candidate-kind ${kindClass}">${escapeHtml(item.kind)}</span>
                  ${isManual ? `<span class="manual-badge">대표 선택됨</span>` : ""}
                  ${item.edited ? `<span class="edited-badge">수정됨</span>` : ""}
                  ${decisionMeta ? `<span class="review-decision-badge ${decisionMeta.className}">${decisionMeta.label}</span>` : ""}
                </div>
                <h4>${escapeHtml(item.title)}</h4>
                <p>${escapeHtml(item.body)}</p>
                <span class="source-note">${escapeHtml(item.source)}</span>
              </div>
              <div class="candidate-actions">
                <button data-review-action="select" data-source="${escapeHtml(key)}" type="button">대표로 선택</button>
                <button data-review-action="preview" data-source="${escapeHtml(key)}" type="button">미리보기</button>
                <button data-review-action="lightbox" data-lightbox-index="${lightboxIndex}" data-source="${escapeHtml(key)}" type="button">크게 보기</button>
                <button data-review-action="mark" data-review-decision="approved" data-source="${escapeHtml(key)}" type="button">적합</button>
                <button data-review-action="mark" data-review-decision="pending" data-source="${escapeHtml(key)}" type="button">보류</button>
                <button data-review-action="mark" data-review-decision="rejected" data-source="${escapeHtml(key)}" type="button">탈락</button>
              </div>
            </article>
          `;
        })
        .join("")
    : `<div class="empty-review">이 필터에 해당하는 후보가 없습니다.</div>`;

  const previewKey = getCandidateKey(previewCandidate);
  const previewLightboxIndex = getCandidateLightboxIndex(previewCandidate);
  const previewKindClass = getCandidateKindClass(previewCandidate?.kind);
  const previewDecision = getCandidateReviewDecision(selectedDino, previewKey);
  const previewDecisionMeta = getCandidateReviewDecisionMeta(previewDecision);
  $("#workflowSteps").innerHTML = `
    <section class="candidate-review-panel">
      <div class="candidate-hero">
        <button class="candidate-stage ${previewCandidate?.src ? "has-real-image can-zoom" : ""}" data-review-action="lightbox" data-lightbox-index="${previewLightboxIndex}" data-source="${escapeHtml(previewKey)}" type="button"${imageStyle(previewCandidate)} ${previewCandidate?.src ? "" : "disabled"}>
          <span class="image-label">${escapeHtml(previewCandidate?.kind || "후보 없음")}</span>
        </button>
        <div class="candidate-hero-copy">
          <div>
            <p class="eyebrow">Candidate Review</p>
            <h3>${escapeHtml(selectedDino.koreanName)}</h3>
            <p class="summary">${escapeHtml(selectedDino.name)} · ${escapeHtml(selectedDino.family)}</p>
          </div>
          <div class="candidate-title-row">
            <span class="candidate-kind ${previewKindClass}">${escapeHtml(previewCandidate?.kind || "none")}</span>
            ${previewKey === manualSource ? `<span class="manual-badge">대표 선택됨</span>` : ""}
            ${previewCandidate?.edited ? `<span class="edited-badge">수정됨</span>` : ""}
            ${previewDecisionMeta ? `<span class="review-decision-badge ${previewDecisionMeta.className}">${previewDecisionMeta.label}</span>` : ""}
          </div>
          <h4>${escapeHtml(previewCandidate?.title || "후보 이미지 없음")}</h4>
          <p>${escapeHtml(previewCandidate?.body || "이 종에는 아직 검수 후보가 없습니다.")}</p>
          <div class="candidate-command-row">
            <button class="primary-action" data-review-action="select" data-source="${escapeHtml(previewKey)}" type="button">대표로 선택</button>
            <button data-review-action="mark" data-review-decision="approved" data-source="${escapeHtml(previewKey)}" type="button">적합</button>
            <button data-review-action="mark" data-review-decision="pending" data-source="${escapeHtml(previewKey)}" type="button">보류</button>
            <button data-review-action="mark" data-review-decision="rejected" data-source="${escapeHtml(previewKey)}" type="button">탈락</button>
            <button data-review-action="mark" data-review-decision="" data-source="${escapeHtml(previewKey)}" type="button">판정 해제</button>
            <button data-review-action="clear" type="button">기본값 복원</button>
            <button data-review-action="atlas" type="button">지도에서 보기</button>
            <button data-review-action="lightbox" data-lightbox-index="${previewLightboxIndex}" data-source="${escapeHtml(previewKey)}" type="button">크게 보기</button>
            <button data-review-action="copy" data-source="${escapeHtml(previewKey)}" type="button">경로 복사</button>
          </div>
        </div>
      </div>

      <div class="identity-gate">
        <div>
          <p class="eyebrow">Identity Gate</p>
          <h4>대표 후보 체크포인트</h4>
        </div>
        <ul>${checklist}</ul>
      </div>

      ${variationPanel}

      ${generationRoutePanel}

      <div class="candidate-filter-row">
        <div class="segmented candidate-filters" role="group" aria-label="Candidate kind filter">
          ${candidateFilterButtons}
        </div>
        <button class="review-export-button" data-review-action="export-data" type="button">\uac80\uc218 \ub370\uc774\ud130 \ub0b4\ubcf4\ub0b4\uae30</button>
      </div>

      <div class="candidate-grid">
        ${candidateCards}
      </div>
    </section>
  `;

  bindReviewEvents(selectedDino);
}

function bindReviewEvents(selectedDino) {
  $$(".review-item").forEach((item) => {
    item.addEventListener("click", (event) => {
      const zoomTarget = event.target.closest("[data-review-thumb-zoom]");
      if (zoomTarget) {
        const dino = getDinoById(zoomTarget.dataset.reviewThumbZoom);
        if (dino) openCandidateLightbox(dino, state.reviewCandidateKindFilter, getPrimaryImage(dino));
        return;
      }
      state.reviewSelectedId = item.dataset.reviewId;
      state.reviewPreviewSource = "";
      renderReview();
    });
  });

  $$("[data-review-queue-kind-filter]").forEach((button) => {
    button.addEventListener("click", () => {
      state.reviewQueueKindFilter = button.dataset.reviewQueueKindFilter;
      const topDino = getTopReviewDino(state.reviewQueueKindFilter, state.reviewSort);
      if (topDino) state.reviewSelectedId = topDino.id;
      state.reviewPreviewSource = "";
      renderReview();
    });
  });

  $$("[data-review-candidate-kind-filter]").forEach((button) => {
    button.addEventListener("click", () => {
      state.reviewCandidateKindFilter = button.dataset.reviewCandidateKindFilter;
      state.reviewPreviewSource = "";
      renderReview();
    });
  });

  $$("[data-review-sort]").forEach((select) => {
    select.addEventListener("change", () => {
      state.reviewSort = select.value;
      const topDino = getTopReviewDino(state.reviewQueueKindFilter, state.reviewSort);
      if (topDino) state.reviewSelectedId = topDino.id;
      state.reviewPreviewSource = "";
      renderReview();
    });
  });

  $$("[data-review-action]").forEach((button) => {
    button.addEventListener("click", () => {
      const action = button.dataset.reviewAction;
      const source = button.dataset.source || state.reviewPreviewSource;
      if (action === "preview") {
        state.reviewPreviewSource = source;
        renderReview();
      }
      if (action === "export-data") {
        downloadReviewDataExport();
      }
      if (action === "lightbox") {
        const index = Number(button.dataset.lightboxIndex);
        const lightboxItems = getCandidatesByKindFilter(selectedDino, state.reviewCandidateKindFilter);
        const lightboxCount = getLightboxItems(lightboxItems).length;
        if (index >= 0 && index < lightboxCount) openLightbox(lightboxItems, index);
      }
      if (action === "select" && source) {
        setManualCandidateSelection(selectedDino, source);
      }
      if (action === "mark" && source) {
        setCandidateReviewDecision(selectedDino, source, button.dataset.reviewDecision || "");
      }
      if (action === "clear") {
        clearManualCandidateSelection(selectedDino);
      }
      if (action === "atlas") {
        state.selectedId = selectedDino.id;
        state.galleryIndex = 0;
        setView("atlas");
      }
      if (action === "copy" && source) {
        copyToClipboard(source);
      }
      if (action === "copy-route") {
        copyToClipboard(getGenerationRouteClipboardText(selectedDino));
      }
    });
  });
}

function bindLightboxEvents() {
  const lightbox = $("#imageLightbox");
  if (!lightbox) return;

  lightbox.addEventListener("click", (event) => {
    const button = event.target.closest("[data-lightbox-action]");
    if (!button) return;
    const action = button.dataset.lightboxAction;
    if (action === "close") closeLightbox();
    if (action === "prev") moveLightbox(-1);
    if (action === "next") moveLightbox(1);
  });

  window.addEventListener("keydown", (event) => {
    if (!state.lightboxItems.length) return;
    if (event.key === "Escape") closeLightbox();
    if (event.key === "ArrowLeft") moveLightbox(-1);
    if (event.key === "ArrowRight") moveLightbox(1);
  });
}

function setView(view) {
  if (view === "review") {
    const topDino = getTopReviewDino(state.reviewQueueKindFilter);
    if (topDino) state.reviewSelectedId = topDino.id;
    state.reviewPreviewSource = "";
  }
  if (view === "assetReview") {
    const frame = $("#assetReviewFrame");
    if (frame) frame.src = `http://127.0.0.1:8792/?atlasAudit=${Date.now()}`;
    state.assetReviewFrameLoaded = true;
  }
  state.view = view;
  $$(".nav-tab").forEach((tab) => tab.classList.toggle("active", tab.dataset.view === view));
  $$(".view").forEach((panel) => panel.classList.remove("active"));
  $(`#${view}View`).classList.add("active");
  if (window.location.hash !== `#${view}`) {
    history.replaceState(null, "", `#${view}`);
  }

  const titles = {
    atlas: "공룡 계통도 맵",
    catalog: "대표 공룡 도감",
    review: "이미지 검수 화면",
  };
  $("#viewTitle").textContent = {
    atlas: "공룡 계통도 맵",
    catalog: "대표 공룡 도감",
    review: "이미지 검수 화면",
  }[view];
  if (view === "assetReview") {
    $("#viewTitle").textContent = "이미지 검수 워크벤치";
  }
  renderAll();
}

function renderAll() {
  renderMetrics();
  renderPhyloMap();
  renderDetail();
  renderCatalog();
  renderReview();
}

function bindMapEvents() {
  const viewport = $("#mapViewport");
  const mapNodes = $("#mapNodes");
  const activePointers = new Map();
  let pinching = false;
  let pinchStartDistance = 0;
  let pinchStartScale = state.map.scale;

  const getPinchMetrics = () => {
    const [first, second] = [...activePointers.values()];
    if (!first || !second) return null;
    const centerX = (first.clientX + second.clientX) / 2;
    const centerY = (first.clientY + second.clientY) / 2;
    return {
      centerX,
      centerY,
      distance: Math.hypot(second.clientX - first.clientX, second.clientY - first.clientY),
    };
  };

  const beginPinch = () => {
    const metrics = getPinchMetrics();
    if (!metrics || metrics.distance <= 0) return;
    pinching = true;
    pinchStartDistance = metrics.distance;
    pinchStartScale = state.map.scale;
    state.map.dragging = false;
    viewport.classList.remove("dragging");
    flushMapPanTransform();
  };

  const resumeDragWithRemainingPointer = () => {
    const remainingPointer = [...activePointers.values()][0];
    if (!remainingPointer) return;
    state.map.dragging = true;
    state.map.startX = remainingPointer.clientX;
    state.map.startY = remainingPointer.clientY;
    state.map.originX = state.map.x;
    state.map.originY = state.map.y;
    viewport.classList.add("dragging");
  };

  mapNodes.addEventListener("click", (event) => {
    const node = event.target.closest(".map-node.taxon");
    const groupNode = event.target.closest(".map-node.group");
    if (groupNode) {
      state.phyloFocusId =
        state.phyloFocusId === groupNode.dataset.phyloFocus ? "" : groupNode.dataset.phyloFocus;
      applyPhyloFocusHighlight();
      return;
    }
    if (!node) return;
    state.selectedId = node.dataset.id;
    state.phyloFocusId = "";
    state.galleryIndex = 0;
    renderAll();
  });

  $("#zoomOut").addEventListener("click", () => zoomMap(state.map.scale - 0.12));
  $("#zoomIn").addEventListener("click", () => zoomMap(state.map.scale + 0.12));
  $("#resetMap").addEventListener("click", fitMapToViewport);

  viewport.addEventListener(
    "wheel",
    (event) => {
      event.preventDefault();
      const direction = event.deltaY > 0 ? -1 : 1;
      zoomMap(state.map.scale + direction * 0.08, event.clientX, event.clientY);
    },
    { passive: false },
  );

  viewport.addEventListener("dblclick", (event) => {
    event.preventDefault();
  });

  viewport.addEventListener("pointerdown", (event) => {
    if (event.button !== 0 || event.target.closest(".map-node")) return;
    activePointers.set(event.pointerId, { clientX: event.clientX, clientY: event.clientY });
    viewport.setPointerCapture(event.pointerId);
    if (activePointers.size === 2) {
      beginPinch();
      return;
    }
    state.map.dragging = true;
    state.map.startX = event.clientX;
    state.map.startY = event.clientY;
    state.map.originX = state.map.x;
    state.map.originY = state.map.y;
    viewport.classList.add("dragging");
  });

  viewport.addEventListener("pointermove", (event) => {
    if (activePointers.has(event.pointerId)) {
      activePointers.set(event.pointerId, { clientX: event.clientX, clientY: event.clientY });
    }
    if (pinching) {
      const metrics = getPinchMetrics();
      if (metrics && pinchStartDistance > 0) {
        zoomMap(pinchStartScale * (metrics.distance / pinchStartDistance), metrics.centerX, metrics.centerY);
      }
      return;
    }
    if (!state.map.dragging) return;
    state.map.x = state.map.originX + event.clientX - state.map.startX;
    state.map.y = state.map.originY + event.clientY - state.map.startY;
    scheduleMapPanTransform();
  });

  viewport.addEventListener("pointerup", (event) => {
    activePointers.delete(event.pointerId);
    if (viewport.hasPointerCapture(event.pointerId)) viewport.releasePointerCapture(event.pointerId);
    if (pinching && activePointers.size < 2) {
      pinching = false;
      if (activePointers.size === 1) resumeDragWithRemainingPointer();
    }
    if (activePointers.size === 0) {
      state.map.dragging = false;
      viewport.classList.remove("dragging");
      flushMapPanTransform();
    }
  });

  const stopDragging = (event) => {
    if (event?.pointerId !== undefined) activePointers.delete(event.pointerId);
    if (pinching && activePointers.size < 2) {
      pinching = false;
      if (activePointers.size === 1) resumeDragWithRemainingPointer();
    }
    if (activePointers.size > 0) return;
    state.map.dragging = false;
    viewport.classList.remove("dragging");
    flushMapPanTransform();
  };

  viewport.addEventListener("pointercancel", stopDragging);
  viewport.addEventListener("lostpointercapture", stopDragging);

  viewport.addEventListener("keydown", (event) => {
    const panAmount = 42;
    if (event.key === "+" || event.key === "=") zoomMap(state.map.scale + 0.12);
    if (event.key === "-") zoomMap(state.map.scale - 0.12);
    if (event.key === "0") fitMapToViewport();
    if (event.key === "ArrowLeft") state.map.x += panAmount;
    if (event.key === "ArrowRight") state.map.x -= panAmount;
    if (event.key === "ArrowUp") state.map.y += panAmount;
    if (event.key === "ArrowDown") state.map.y -= panAmount;
    if (["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown"].includes(event.key)) {
      event.preventDefault();
      applyMapTransform();
    }
  });

  window.addEventListener("resize", fitMapToViewport);
}

function bindEvents() {
  $$(".nav-tab").forEach((tab) => {
    tab.addEventListener("click", () => setView(tab.dataset.view));
  });

  window.addEventListener("hashchange", () => {
    const nextView = window.location.hash.replace("#", "");
    if (["atlas", "catalog", "review", "assetReview"].includes(nextView) && nextView !== state.view) {
      setView(nextView);
    }
  });

  $("#searchInput").addEventListener("input", (event) => {
    state.search = event.target.value;
    renderAll();
  });

  $("#dietFilter").addEventListener("click", (event) => {
    const button = event.target.closest("button");
    if (!button) return;
    state.diet = button.dataset.diet;
    $$("#dietFilter button").forEach((item) => item.classList.toggle("active", item === button));
    renderAll();
  });

  $("#levelFilter").addEventListener("click", (event) => {
    const button = event.target.closest("button");
    if (!button) return;
    state.knowledgeLevel = button.dataset.level;
    $$("#levelFilter button").forEach((item) => item.classList.toggle("active", item === button));
    renderAll();
  });

  $("#periodSort").addEventListener("change", (event) => {
    state.sort = event.target.value;
    renderCatalog();
  });

  $("#resetFilters").addEventListener("click", () => {
    state.search = "";
    state.diet = "all";
    state.knowledgeLevel = "all";
    state.sort = "updated";
    $("#searchInput").value = "";
    $("#periodSort").value = state.sort;
    $$("#dietFilter button").forEach((button) =>
      button.classList.toggle("active", button.dataset.diet === "all"),
    );
    $$("#levelFilter button").forEach((button) =>
      button.classList.toggle("active", button.dataset.level === "all"),
    );
    renderAll();
  });

  bindMapEvents();
  bindLightboxEvents();
}

const initialView = window.location.hash.replace("#", "");
if (["atlas", "catalog", "review"].includes(initialView)) {
  state.view = initialView;
}

bindEvents();
setView(state.view);
requestAnimationFrame(fitMapToViewport);
